Lemma iv_subtract_cover : forall b sz lo hi x k,
  u b + u sz <= 2^64 -> u b <= x -> x + k <= u b + u sz -> 0 < k ->
  (x + k <= lo \/ hi <= x) ->
  exists b' sz', In (b', sz') (iv_subtract b sz lo hi) /\ u b' <= x /\ x + k <= u b' + u sz'.
Proof.
